namespace App.Infrastructure;

public static class GeneratedTimers
{
    /// <summary>Moves records whose timer has passed; returns how many moved.</summary>
    public static async Task<int> RunAsync(AppDbContext db, TimeProvider time, CancellationToken ct)
    {
        var now = time.GetUtcNow();
        var today = DateOnly.FromDateTime(now.UtcDateTime);
        var moved = 0;
        // ParkingSession.send_warning: active -> warning_sent when plannedEndAt has passed.
        foreach (var item in await db.Set<ParkingSession>().Where(x => (x.Status == ParkingSessionState.Active) && x.PlannedEndAt != null && x.PlannedEndAt <= now).ToListAsync(ct))
        {
            item.Status = ParkingSessionState.WarningSent;
            DomainEvents.Raise(db, "ParkingSessionSentWarning", item, item.Id, time);
            moved++;
        }
        // ParkingSession.expire_after_warning: timer endsAt is not a date of ParkingSession; wire it in custom.
        if (moved > 0) await db.SaveChangesAsync(ct);
        return moved;
    }
}
